SELECT (SUM(CASE WHEN Segment = 'Premium' THEN 1.0 ELSE 0.0 END) * 100.0) / COUNT(*) AS percentage
FROM gasstations
WHERE Country = 'SVK';

SELECT SUM(cost) AS total_cost
FROM expense
WHERE lower(expense_description) LIKE '%pizza%';

SELECT MAX(total_spent) FROM (
  SELECT SUM(budget.spent) AS total_spent
  FROM budget
  JOIN event ON budget.link_to_event = event.event_id
  GROUP BY budget.link_to_event, event.event_name
);

SELECT CASE WHEN total=0 THEN 0 ELSE (100.0*cnt)/total END AS percentage
FROM (
  SELECT
    (SELECT COUNT(DISTINCT member_id) FROM member WHERE t_shirt_size = 'Medium') AS total,
    (SELECT COUNT(DISTINCT member.member_id)
     FROM member
     JOIN income ON member.member_id = income.link_to_member
     WHERE member.t_shirt_size = 'Medium' AND income.amount = 50 AND income.source = 'Student_Club'
    ) AS cnt
);

SELECT "aCL IgG", "aCL IgM", "aCL IgA"
FROM Examination
WHERE ID IN (
  SELECT ID FROM Examination WHERE Diagnosis = 'SLE' AND "Examination Date" = '1994-02-19'
)
AND "Examination Date" = '1993-11-12';

SELECT (
  ( (SELECT milliseconds FROM results r JOIN races ra ON r.raceId = ra.raceId WHERE ra.year = 2008 AND ra.name = 'Australian Grand Prix' AND r.milliseconds IS NOT NULL ORDER BY r.positionOrder DESC LIMIT 1)
  - (SELECT milliseconds FROM results r2 JOIN races ra2 ON r2.raceId = ra2.raceId WHERE ra2.year = 2008 AND ra2.name = 'Australian Grand Prix' AND r2.positionOrder = 1 AND r2.milliseconds IS NOT NULL LIMIT 1)
  ) * 100.0
  / (SELECT milliseconds FROM results r3 JOIN races ra3 ON r3.raceId = ra3.raceId WHERE ra3.year = 2008 AND ra3.name = 'Australian Grand Prix' AND r3.milliseconds IS NOT NULL ORDER BY r3.positionOrder DESC LIMIT 1)
) AS percentage;

SELECT
  (SELECT group_concat(code, ',') FROM (SELECT code FROM drivers ORDER BY dob DESC LIMIT 3)),
  (SELECT COUNT(*) FROM (SELECT nationality FROM drivers ORDER BY dob DESC LIMIT 3) WHERE nationality IN ('Dutch','Netherlands','Netherlandic'));

SELECT CASE WHEN denom = 0 THEN 0.0 ELSE 100.0 * num / denom END AS percentage
FROM (
  SELECT
    (SELECT COUNT(*) FROM superhero s JOIN colour c ON s.eye_colour_id = c.id WHERE lower(c.colour) = 'blue') AS num,
    (SELECT COUNT(*) FROM superhero WHERE eye_colour_id IS NOT NULL) AS denom
);

SELECT CASE WHEN v.votes_count=0 THEN NULL ELSE p.posts_count*1.0/v.votes_count END
FROM (SELECT COUNT(*) AS posts_count FROM posts WHERE OwnerUserId = 24) p,
     (SELECT COUNT(*) AS votes_count FROM votes WHERE UserId = 24) v;

SELECT
  (COALESCE((SELECT SUM(p.ViewCount) FROM posts p JOIN users u ON p.OwnerUserId = u.Id WHERE u.DisplayName = 'Mornington'),0)
   + COALESCE((SELECT SUM(ViewCount) FROM posts WHERE OwnerUserId IS NULL AND OwnerDisplayName = 'Mornington'),0)
   - COALESCE((SELECT SUM(p.ViewCount) FROM posts p JOIN users u ON p.OwnerUserId = u.Id WHERE u.DisplayName = 'Amos'),0)
   - COALESCE((SELECT SUM(ViewCount) FROM posts WHERE OwnerUserId IS NULL AND OwnerDisplayName = 'Amos'),0)
  ) AS Difference;

SELECT ExcerptPostId, WikiPostId
FROM tags
WHERE TagName = 'sample';

SELECT CASE WHEN total = 0 THEN 0.0 ELSE (100.0 * no_f) / total END
FROM (
  SELECT
    (SELECT COUNT(DISTINCT molecule_id) FROM molecule WHERE label = '+') AS total,
    (SELECT COUNT(DISTINCT molecule_id) FROM molecule WHERE label = '+' AND molecule_id NOT IN (
      SELECT molecule_id FROM atom WHERE lower(element) = 'f' OR lower(element) LIKE 'fluor%'
    )) AS no_f
);

SELECT (
  (
    (SELECT t2.balance FROM trans t2 WHERE t2.account_id = (SELECT l.account_id FROM loan l WHERE l.date = '1993-07-05' ORDER BY l.loan_id ASC LIMIT 1) AND t2.date = '1998-12-27' ORDER BY t2.trans_id DESC LIMIT 1)
    -
    (SELECT t1.balance FROM trans t1 WHERE t1.account_id = (SELECT l.account_id FROM loan l WHERE l.date = '1993-07-05' ORDER BY l.loan_id ASC LIMIT 1) AND t1.date = '1993-03-22' ORDER BY t1.trans_id DESC LIMIT 1)
  ) * 1.0
  / NULLIF((SELECT t1b.balance FROM trans t1b WHERE t1b.account_id = (SELECT l.account_id FROM loan l WHERE l.date = '1993-07-05' ORDER BY l.loan_id ASC LIMIT 1) AND t1b.date = '1993-03-22' ORDER BY t1b.trans_id DESC LIMIT 1), 0)
) AS increase_rate;

SELECT 100.0 * COUNT(DISTINCT CASE WHEN status = 'C' THEN account_id END) / COUNT(DISTINCT account_id) AS percentage
FROM loan
WHERE amount < 100000;

SELECT CASE WHEN d.total_males=0 THEN 0 ELSE 100.0 * n.weekly_males / d.total_males END
FROM (SELECT COUNT(DISTINCT client_id) AS total_males FROM client WHERE gender = 'M') d
CROSS JOIN (SELECT COUNT(DISTINCT disp.client_id) AS weekly_males FROM disp JOIN account ON disp.account_id = account.account_id JOIN client c ON c.client_id = disp.client_id WHERE c.gender = 'M' AND account.frequency LIKE '%TYDNE%') n;
